// Random number generated by computer and guessed by user

#include <iostream>
#include <cstdlib>
#include <ctime>

using namespace std;

int main()
{
	srand(time(0));
	
	int num = (rand() % 100) +1;
	int a;
	cout<<"********** WELCOME TO NUMBER GUESSING GAME **********"<<endl;
	cout<<"INSTRUCTIONS:\n 1. User has to enter a number between (0-100).\n 2. The game will continue until the number is guessed correctly by the user."<<endl;
	int guesses=0;
	do{
		
		cout<<"Enter a number: ";
		cin>>a;
		guesses++;
		
	
		if (num<a)
		{
			cout<<"Your guess is too high!"<<endl;
			cout<<"**************************"<<endl;
		}
		else 
		{
			cout<<"Your guess is too low!"<<endl;
			cout<<"**************************"<<endl;

		}
		
		if (guesses<10)
		{
			cout<<"You can continue....."<<endl;
			continue;
		}
		else
		{
			break;
		}
		
	}while(num!=a);
	
	

	cout<<"Number of guesses: "<<guesses<<endl;
	cout<<"*****************************"<<endl;
	cout<<"***** YOU HAVE GUESSED THE NUMBER! *****"<<endl;
	cout<<"The number is :"<<a<<endl;
    cout<<"----- YOU WON -----"<<endl;
	return 0;
}
